import time

def construct():
    N = 17
    MIN_DIST = 6
    
    # Quadratic residues modulo 17
    residues = set((i * i) % 17 for i in range(17))
    # 0 is a residue (0^2=0), but typically for QR codes we look at non-zero residues for the generator vector structure?
    # Let's check the definition.
    # The QR code of length p is generated by the circulant matrix with first row g where g_i = 1 if i is a QR mod p.
    # If 0 is included, g_0 = 1.
    # If 0 is excluded, g_0 = 0.
    # For p=17, the code with g_0=0 has dimension 9 and distance 6.
    # The code with g_0=1 is the extended code or a different variant?
    # Actually, the [17,9,6] code usually has generator matrix with first row having weight 8 (non-zero residues).
    # Let's use g_0=0.
    
    g = [0] * N
    for i in range(1, N):
        if (i * i) % 17 == i: # This is wrong check. (i*i)%17 is the square. We want to know if i is in the set of squares.
            pass
    # Correct check:
    residues = set((i * i) % 17 for i in range(1, 17)) # Non-zero residues
    for i in range(N):
        if i in residues:
            g[i] = 1
            
    # Generate generator matrix rows (cyclic shifts)
    rows = []
    for k in range(9):
        row = g[:]
        # Shift left by k
        row = row[k:] + row[:k]
        rows.append(row)
        
    # Enumerate all 2^9 combinations
    words = []
    for mask in range(2**9):
        word_int = 0
        for i in range(9):
            if (mask >> i) & 1:
                # XOR the row into word_int
                # We can do this by converting row to int and XORing
                row_int = 0
                for j in range(N):
                    if rows[i][j]:
                        row_int |= (1 << j)
                # We need to precompute row_ints for speed
                pass
        
    # Optimization: Precompute row integers
    row_ints = []
    for row in rows:
        r_int = 0
        for j in range(N):
            if row[j]:
                r_int |= (1 << j)
        row_ints.append(r_int)
        
    for mask in range(2**9):
        w = 0
        for i in range(9):
            if (mask >> i) & 1:
                w ^= row_ints[i]
        words.append(w)
        
    return words
